import os, sys, pty, select, time, termios, tty
def drive(cmd, inputs, wait=0.4, env=None):
    e = dict(os.environ)
    if env: e.update(env)
    pid, fd = pty.fork()
    if pid == 0:
        os.execvpe("/bin/sh", ["/bin/sh", "-c", cmd], e)
    out = b""
    def pump(t):
        nonlocal out
        end = time.time() + t
        while time.time() < end:
            r,_,_ = select.select([fd], [], [], 0.05)
            if r:
                try: d = os.read(fd, 65536)
                except OSError: return False
                if not d: return False
                out += d
    pump(wait)
    for line in inputs:
        os.write(fd, line)
        if pump(wait) is False: break
    pump(wait)
    try: os.close(fd)
    except OSError: pass
    try: os.waitpid(pid, 0)
    except ChildProcessError: pass
    return out
if __name__ == "__main__":
    cmd = sys.argv[1]
    ins = [l.encode().decode('unicode_escape').encode('latin1') for l in sys.argv[2:]]
    print(repr(drive(cmd, ins)))
